import { loadFont as loadTxt } from "@remotion/google-fonts/Inter";
import { loadFont as loadHead } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, useCurrentFrame } from "remotion";
import { NR_IN, NR_OUT, NR_T, V3_DUR, WARP_N, WARP_O } from "./warp";

// REDE SABER MAIS — Plano de Educação. VSL horizontal (1920×1080) de 3 min, toda em motion, que apresenta a página
// lp.redesabermais.com e leva ao agendamento da apresentação. Identidade da página e da arte do cliente: fundo claro,
// azul-marinho nos títulos, laranja no botão, blocos arredondados em amarelo, azul e rosa com ícone branco, Montserrat.
// Limpo: cores chapadas, sem brilho. Locução (ElevenLabs) com 179,5 s sem silêncio morto; tempos = palavra + 0,15 s.
// v3 (13/10): voz nova, mais curta. Os tempos abaixo continuam os da v2; `warp.ts` converte o tempo do vídeo novo no
// antigo. A cena da NR-1 e do ESG é nova e corre no próprio relógio (NR0 + segundos desde a entrada).

const { fontFamily: HEAD } = loadHead("normal", { weights: ["600", "700", "800"], subsets: ["latin", "latin-ext"] });
const { fontFamily: TXT } = loadTxt("normal", { weights: ["500", "600"], subsets: ["latin", "latin-ext"] });

export const SM_FPS = 30;
export const SM_FRAMES = Math.round(V3_DUR * SM_FPS);
const LOGO = "https://lp.redesabermais.com/logo/logo-rede-saber-mais.png"; // logo oficial, lido direto do site do cliente

const NAVY = "#0F2A4A";
const ORANGE = "#E8722C";
const YEL = "#F4B63F";
const BLU = "#2D6CDF";
const PINK = "#EE4C7C";
const BG = "#FAF7F1";
const TINT: Record<string, string> = { [YEL]: "#FBE7B5", [BLU]: "#CFDFF8", [PINK]: "#F9CBD8", [ORANGE]: "#F9D8C2", [NAVY]: "#C9D3E0" };
const MUTED = "#5B6B7F";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.5));
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.42) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const rise = (t: number, at: number, dy = 40, d = 0.5): React.CSSProperties => {
  const e = k(t, at, d);
  return { opacity: e, transform: `translateY(${((1 - e) * dy).toFixed(1)}px)` };
};
const zoom = (t: number, at: number, d = 0.42): React.CSSProperties => ({ opacity: t >= at ? 1 : 0, transform: `scale(${pop(t, at, d).toFixed(3)})` });

// ───────── ícones (traço simples, cor herdada) ─────────
const Icon: React.FC<{ n: string; s: number; w?: number }> = ({ n, s, w = 2 }) => {
  const P = (d: string, fill = false) => <path d={d} fill={fill ? "currentColor" : "none"} />;
  const body: Record<string, React.ReactNode> = {
    heart: P("M12 20s-7.500-4.700-7.500-10.200A4.300 4.300 0 0 1 12 7.200a4.300 4.300 0 0 1 7.500 2.600C19.500 15.300 12 20 12 20z", true),
    star: P("M12 3.500l2.600 5.300 5.900.900-4.300 4.100 1 5.800L12 16.900 6.800 19.600l1-5.800-4.300-4.100 5.900-.900z", true),
    book: P("M3.500 5.500c2.800-1 5.800-.800 8.500.900 2.700-1.700 5.700-1.900 8.500-.900v12.800c-2.800-1-5.800-.800-8.500.900-2.700-1.700-5.700-1.900-8.500-.900zM12 6.400v12.800"),
    brief: P("M4 8h16v11H4zM9 8V5.500h6V8M4 13h16"),
    spark: P("M11 3l1.900 5.600L18.500 10.500l-5.600 1.900L11 18l-1.900-5.600L3.500 10.500l5.600-1.900zM18.500 14.500l.900 2.600 2.600.900-2.600.900-.900 2.600-.900-2.600-2.600-.900 2.600-.900z", true),
    family: (
      <>
        <circle cx={8} cy={7.500} r={2.800} />
        <circle cx={16.500} cy={9} r={2.200} />
        {P("M2.800 20c0-3.600 2.300-6 5.200-6s5.200 2.400 5.200 6M13.800 20c.100-2.800 1.200-4.600 3-4.600 2 0 3.500 1.700 3.500 4.600")}
      </>
    ),
    incl: (
      <>
        <circle cx={12} cy={5} r={2.200} />
        {P("M4.500 9.500c5 1.400 10 1.400 15 0M12 10.500v5M12 15.500l-3.500 5M12 15.500l3.500 5")}
      </>
    ),
    lib: P("M5 4.500h3.500v15H5zM10.500 4.500H14v15h-3.500zM15.800 6.200l3.300-.900 3.200 13.400-3.300.900z"),
    tag: (
      <>
        {P("M3.500 12.500V4.500h8l9 9-8 8z")}
        <circle cx={8} cy={9} r={1.400} />
      </>
    ),
    cross: P("M9.500 4h5v5.500H20v5h-5.500V20h-5v-5.500H4v-5h5.500z"),
    scale: P("M12 4v16M6 20h12M5 7.500h14M5 7.500l-2.500 6a2.800 2.800 0 0 0 5 0zM19 7.500l-2.500 6a2.800 2.800 0 0 0 5 0z"),
    award: (
      <>
        <circle cx={12} cy={9} r={5} />
        {P("M9 13.500L7.500 21l4.500-2.500 4.500 2.500L15 13.500")}
      </>
    ),
    trophy: P("M8 4h8v5a4 4 0 0 1-8 0zM8 6H4.500c0 3 1.500 4.500 3.800 4.500M16 6h3.500c0 3-1.500 4.500-3.800 4.500M12 13v4M8.500 20h7M10 17h4v3h-4z"),
    check: P("M4.500 12.500l5 5L19.500 7"),
    x: P("M6 6l12 12M18 6L6 18"),
    build: P("M4 20V5.500h9V20M13 10h7v10M2.500 20h19M7 9h3M7 12.500h3M7 16h3M16 13.500h1.500M16 17h1.500"),
    users: (
      <>
        <circle cx={7} cy={8} r={2.500} />
        <circle cx={17} cy={8} r={2.500} />
        <circle cx={12} cy={13.500} r={2.500} />
        {P("M2.500 16c.300-2.300 2-3.800 4.500-3.800M21.500 16c-.300-2.300-2-3.800-4.500-3.800M7 21c.300-2.700 2.300-4.200 5-4.200s4.700 1.500 5 4.200")}
      </>
    ),
    flag: P("M5 21V4M5 5h11l-2 3.500 2 3.500H5"),
    cap: P("M2.500 9.500L12 5l9.500 4.500L12 14zM6.500 11.800V16c1.500 1.600 3.400 2.400 5.500 2.400s4-.800 5.500-2.400v-4.200M21.500 9.500V15"),
    land: P("M3 9.500L12 4l9 5.500M4.500 9.500h15M6 12v6M10 12v6M14 12v6M18 12v6M3.500 20.500h17"),
    home: P("M3.500 11.500L12 4.500l8.500 7M6 10v9.500h12V10M10 19.500v-5h4v5"),
    pencil: P("M4.500 19.500l1-4.500L16.500 4l3.500 3.500L9 18.500zM14 6.500l3.500 3.500"),
    target: (
      <>
        <circle cx={12} cy={12} r={8} />
        <circle cx={12} cy={12} r={4} />
        <circle cx={12} cy={12} r={0.800} fill="currentColor" />
      </>
    ),
    cal: P("M4 6.500h16v13H4zM4 10.500h16M8 4v4M16 4v4M8.500 14.500l2.500 2.500 4.500-4.500"),
    chat: P("M4 5.500h16v10.500h-8.500L7 20v-4H4z"),
    doc: P("M6 3.500h8.500L18.500 7.500v13H6zM14 3.500v4.500h4.500M9 12h6M9 15.500h6"),
    key: (
      <>
        <circle cx={8} cy={12} r={3.500} />
        {P("M11.500 12h9M17 12v3M20.500 12v2")}
      </>
    ),
    rocket: P("M12 3.500c3 2.200 4.500 5.500 4.500 9.500l-2 2.500h-5l-2-2.500c0-4 1.500-7.300 4.500-9.500zM7.500 13l-3 3 3 .500M16.500 13l3 3-3 .500M10.500 18.500l1.500 2.500 1.500-2.500M12 8.500v2"),
  };
  return (
    <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={w} strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink: 0 }}>
      {body[n]}
    </svg>
  );
};
// bloco arredondado colorido com ícone branco: a peça da marca
const Tile: React.FC<{ c: string; s: number; icon?: string; style?: React.CSSProperties; children?: React.ReactNode; soft?: boolean }> = ({ c, s, icon, style, children, soft }) => (
  <div style={{ width: s, height: s, borderRadius: s * 0.26, background: soft ? TINT[c] : c, color: soft ? c : "#FFFFFF", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, ...style }}>
    {icon ? <Icon n={icon} s={s * 0.52} w={1.900} /> : children}
  </div>
);
type W = [string, number, boolean?];
// título: as palavras entram no tempo da fala; `true` = destaque em laranja
const Head: React.FC<{ t: number; items: W[]; size?: number; width?: number; color?: string; hl?: string; align?: "left" | "center"; weight?: number }> = ({ t, items, size = 84, width = 860, color = NAVY, hl = ORANGE, align = "left", weight = 800 }) => (
  <div style={{ width, display: "flex", flexWrap: "wrap", justifyContent: align === "center" ? "center" : "flex-start", columnGap: size * 0.26, rowGap: size * 0.06 }}>
    {items.map(([w, at, h], i) => {
      const e = interpolate(t, [at, at + 0.42], [0, 1], { ...cl, easing: BACK });
      return (
        <span key={i} style={{ position: "relative", fontFamily: HEAD, fontWeight: weight, fontSize: size, lineHeight: 1.08, letterSpacing: "-0.02em", color: h ? hl : color, display: "inline-block", whiteSpace: "nowrap", opacity: interpolate(t, [at, at + 0.16], [0, 1], cl), transform: `translateY(${((1 - e) * size * 0.6).toFixed(1)}px) scale(${(h ? 0.62 + 0.38 * e : 0.9 + 0.1 * e).toFixed(3)})`, transformOrigin: "50% 85%" }}>
          {h ? <span style={{ position: "absolute", left: -6, right: -6, bottom: size * 0.04, height: size * 0.17, borderRadius: size * 0.09, background: color === "#FFFFFF" ? "rgba(255,255,255,0.16)" : "rgba(244,182,63,0.5)", transform: `scaleX(${k(t, at + 0.18, 0.5).toFixed(3)})`, transformOrigin: "0% 50%", zIndex: -1 }} /> : null}
          {w}
        </span>
      );
    })}
  </div>
);
const Kicker: React.FC<{ t: number; at: number; children: string; color?: string }> = ({ t, at, children, color = ORANGE }) => (
  <div style={{ display: "flex", alignItems: "center", gap: 16, ...rise(t, at, 20) }}>
    <div style={{ width: 44 * k(t, at, 0.6), height: 5, background: YEL, borderRadius: 3 }} />
    <div style={{ fontFamily: HEAD, fontWeight: 700, fontSize: 28, letterSpacing: "0.18em", color, textTransform: "uppercase", whiteSpace: "nowrap" }}>{children}</div>
  </div>
);
const Body: React.FC<{ children: React.ReactNode; size?: number; color?: string; style?: React.CSSProperties }> = ({ children, size = 40, color = MUTED, style }) => <div style={{ fontFamily: TXT, fontWeight: 500, fontSize: size, lineHeight: 1.32, color, ...style }}>{children}</div>;
const Row: React.FC<{ t: number; at: number; icon?: string; c?: string; children: string; size?: number; light?: boolean }> = ({ t, at, icon = "check", c = BLU, children, size = 44, light }) => (
  <div style={{ position: "relative", alignSelf: "flex-start", display: "flex", alignItems: "center", gap: 24, padding: `${size * 0.16}px ${size * 0.5}px ${size * 0.16}px 0`, opacity: k(t, at, 0.3), transform: `translateX(${((1 - interpolate(t, [at, at + 0.5], [0, 1], { ...cl, easing: BACK })) * 160).toFixed(1)}px) scale(${(1 + 0.08 * (t >= at ? 1 - k(t, at + 0.12, 0.55) : 0)).toFixed(4)})`, transformOrigin: "0% 50%" }}>
    <div style={{ position: "absolute", left: size * 0.75, top: 0, bottom: 0, right: 0, borderRadius: size * 0.5, background: TINT[c] ?? TINT[BLU], transformOrigin: "0% 50%", transform: `scaleX(${k(t, at + 0.05, 0.55).toFixed(3)})`, opacity: light ? 0 : 1 - 0.6 * k(t, at + 1.5, 0.9) }} />
    <div style={{ position: "relative", transform: `scale(${pop(t, at + 0.05, 0.4).toFixed(3)}) rotate(${(Math.sin(t * 2.4 + at) * 5).toFixed(2)}deg) translateY(${(Math.sin(t * 3 + at) * 4).toFixed(1)}px)` }}>
      <Tile c={c} s={size * 1.5} icon={icon} />
    </div>
    <div style={{ position: "relative", fontFamily: HEAD, fontWeight: 700, fontSize: size, lineHeight: 1.14, color: light ? "#FFFFFF" : NAVY, letterSpacing: "-0.01em" }}>{children}</div>
  </div>
);
// anéis pastel abrindo atrás de um bloco grande
const Rings: React.FC<{ t: number; from: number; s: number; c: string }> = ({ t, from, s, c }) => (
  <>
    {[0, 0.5].map((dl) => {
      const u = t > from ? ((t - from) * 0.45 + dl) % 1 : -1;
      return u >= 0 ? <div key={dl} style={{ position: "absolute", left: 0, top: 0, width: s, height: s, borderRadius: s * 0.26, border: `10px solid ${TINT[c] ?? TINT[BLU]}`, boxSizing: "border-box", opacity: 1 - u, transform: `scale(${(1 + u * 0.42).toFixed(3)})` }} /> : null;
    })}
  </>
);
const Float: React.FC<{ t: number; i?: number; amp?: number; children: React.ReactNode }> = ({ t, i = 0, amp = 10, children }) => <div style={{ transform: `translateY(${(Math.sin(t * 1.9 + i * 1.4) * amp).toFixed(1)}px) rotate(${(Math.sin(t * 1.3 + i * 0.9) * 1.6).toFixed(2)}deg)` }}>{children}</div>;
const Card: React.FC<{ children: React.ReactNode; style?: React.CSSProperties }> = ({ children, style }) => <div style={{ background: "#FFFFFF", borderRadius: 36, boxShadow: "0 24px 60px rgba(15,42,74,0.10)", border: "2px solid #EDE7DB", boxSizing: "border-box", ...style }}>{children}</div>;

// ───────── fundo: claro (ou azul-marinho), com os blocos da marca flutuando nas bordas ─────────
const DECO: [number, number, number, string, string][] = [
  [1790, 40, 420, YEL, "heart"],
  [1880, 560, 380, BLU, "star"],
  [1700, 1010, 400, PINK, "book"],
  [-60, 1010, 340, BLU, "star"],
  [60, -70, 300, PINK, "heart"],
];
const Sc: React.FC<{ t: number; a: number; b: number; navy?: boolean; children: React.ReactNode }> = ({ t, a, b, navy, children }) => {
  if (t < a || t >= b) return null;
  const n = Math.max(0, SCENE_STARTS.indexOf(a));
  const p = lin(t, a, Math.min(b, a + 12));
  const dir = n % 2 ? -1 : 1;
  const punch = EVENTS.reduce((m, e) => (e >= a - 0.01 && e < b && t >= e ? Math.max(m, 1 - k(t, e, 0.5)) : m), 0);
  const sc = (n % 3 === 1 ? 1.04 - 0.05 * p : 0.985 + 0.055 * p) * (1 + 0.022 * punch);
  return (
    <AbsoluteFill style={{ background: navy ? NAVY : BG, overflow: "hidden" }}>
      {DECO.map(([x, y, s, c, ic], i) => (
        <div key={i} style={{ position: "absolute", left: x - s / 2 + Math.sin(t * 0.8 + i * 1.7) * 70, top: y - s / 2 + Math.cos(t * 0.66 + i) * 56, transform: `rotate(${(45 + (t - a) * (i % 2 ? -7 : 7) + i * 20).toFixed(2)}deg) scale(${(0.7 + 0.3 * k(t, a + i * 0.06, 0.9) + 0.05 * Math.sin(t * 1.1 + i)).toFixed(3)})`, opacity: navy ? 0.09 : 0.7 }}>
          <Tile c={navy ? "#FFFFFF" : c} s={s} soft={!navy} style={{ color: navy ? NAVY : "#FFFFFF" }}>
            <div style={{ transform: `rotate(${(-45 - (t - a) * (i % 2 ? -7 : 7) - i * 20).toFixed(2)}deg)`, color: navy ? NAVY : "#FFFFFF" }}>
              <Icon n={ic} s={s * 0.4} />
            </div>
          </Tile>
        </div>
      ))}
      <AbsoluteFill style={{ transform: `translate(${((0.5 - p) * 40 * dir + Math.sin(t * 1.1) * 7).toFixed(1)}px, ${(Math.cos(t * 0.9) * 7 + (n % 2 ? (p - 0.5) * 16 : 0)).toFixed(1)}px) scale(${sc.toFixed(4)}) rotate(${((p - 0.5) * 0.7 * dir).toFixed(3)}deg)`, transformOrigin: "50% 46%" }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};
// troca de cena: um bloco colorido atravessa a tela
const Cut: React.FC<{ t: number; at: number; i: number }> = ({ t, at, i }) => {
  const d = 0.28;
  if (t < at - d || t > at + d) return null;
  const dir = i % 2 ? -1 : 1;
  const x1 = (lin(t, at - d, at + d - 0.09) * 2 - 1) * 2500 * dir;
  const x2 = (lin(t, at - d + 0.09, at + d) * 2 - 1) * 2500 * dir;
  const blk: React.CSSProperties = { position: "absolute", left: -200, top: -100, width: 2320, height: 1280, borderRadius: 200 };
  return (
    <>
      <div style={{ ...blk, background: [YEL, BLU, PINK, ORANGE][i % 4], transform: `translateX(${x1.toFixed(0)}px) rotate(${(-4 * dir).toFixed(0)}deg)` }} />
      <div style={{ ...blk, background: [BLU, PINK, ORANGE, YEL][i % 4], transform: `translateX(${x2.toFixed(0)}px) rotate(${(3 * dir).toFixed(0)}deg)` }} />
    </>
  );
};
const abs = (left: number, top: number, extra?: React.CSSProperties): React.CSSProperties => ({ position: "absolute", left, top, ...extra });

// catraca: poste e três braços que giram quando alguém passa
const Turnstile: React.FC<{ t: number; spin: number; blocked?: boolean }> = ({ spin, blocked }) => (
  <svg width={260} height={320} viewBox="0 0 130 160">
    <rect x={50} y={62} width={30} height={92} rx={8} fill={NAVY} />
    <rect x={36} y={148} width={58} height={10} rx={5} fill={NAVY} />
    <g transform={`rotate(${spin} 65 62)`}>
      {[0, 120, 240].map((r) => (
        <rect key={r} x={61} y={8} width={8} height={54} rx={4} fill={blocked ? PINK : ORANGE} transform={`rotate(${r} 65 62)`} />
      ))}
    </g>
    <circle cx={65} cy={62} r={13} fill={NAVY} />
    <circle cx={65} cy={62} r={5} fill="#FFFFFF" />
  </svg>
);

const C = { s2: 4.35, s3: 19.6, s3b: 25.0, s4: 34.8, s5: 43.2, p1: 50.6, p2: 66.3, p3: 74.7, p4: 83.7, p5: 90.2, s6: 99.05, s7: 113.3, s8: 124.8, s9: 137.5, s10: 151.5, s11: 156.45, s12: 164.2, end: 175.65 };
const CUTS = Object.values(C);
const NR0 = 1000; // relógio próprio da cena NR-1/ESG, longe dos tempos da v2
const SCENE_STARTS = [0, ...CUTS, NR0];
const EVENTS = [0.27, 0.93, 1.55, 2.41, 2.95, 11.59, 13.19, 14.69, 16.67, 23.18, 27.75, 28.91, 30.65, 32.59, 35.67, 38.43, 42.12, 43.3, 47.4, 47.9, 48.4, 48.9, 49.4, 49.64,
  51.38, 52.91, 53.55, 55.5, 60.27, 62.17, 62.92, 64.08, 65.16, 67.82, 70.24, 72.0, 73.4, 76.68, 77.98, 79.12, 80.82, 84.83, 85.83, 91.47, 92.53, 94.19, 96.15, 97.56,
  101.5, 102.9, 103.5, 104.1, 108.26, 111.91, 115.19, 116.47, 117.75, 119.87, 121.67, 127.2, 129.24, 131.96, 135.07, 139.65, 140.39, 141.37, 142.47, 144.13,
  147.39, 148.23, 149.43, 153.2, 154.77, 158.06, 159.34, 161.18, 163.08, 164.94, 166.0, 167.75, 170.1, 175.75, 178.19, 179.4,
  NR0 + NR_T.plano, NR0 + NR_T.atender, NR0 + NR_T.nr, NR0 + NR_T.esg];

const PILLARS: { a: number; b: number; c: string; icon: string; title: W[]; rows: [string, number, string][] }[] = [
  { a: C.p1, b: C.p2, c: BLU, icon: "brief", title: [["Educação", 51.38], ["Profissional", 51.8, true]], rows: [["Cursos", 52.91, "book"], ["Capacitações corporativas", 53.55, "build"], ["Trilhas de desenvolvimento", 55.5, "rocket"]] },
  { a: C.p2, b: C.p3, c: ORANGE, icon: "spark", title: [["Inteligência", 67.12], ["Artificial", 67.82, true], ["aplicada", 68.5], ["à educação", 68.98]], rows: [["Apoio individual ao estudo", 70.24, "users"], ["Tira dúvidas na hora em que aparecem", 72.0, "chat"]] },
  { a: C.p3, b: C.p4, c: YEL, icon: "family", title: [["Educação para", 75.68], ["toda a família", 76.68, true]], rows: [["Reforço escolar", 77.98, "pencil"], ["Preparação para o Enem", 79.12, "target"], ["Conteúdos para diferentes idades", 80.82, "star"]] },
  { a: C.p4, b: C.p5, c: PINK, icon: "incl", title: [["Educação", 84.25], ["Inclusiva", 84.83, true]], rows: [["Recursos para diferentes necessidades de aprendizagem", 85.83, "heart"]] },
  { a: C.p5, b: C.s6, c: NAVY, icon: "lib", title: [["Clube", 90.77], ["do Livro", 91.47, true]], rows: [["Livros e audiolivros", 92.53, "book"], ["Saúde mental", 94.19, "heart"], ["Educação financeira", 96.15, "tag"], ["Qualidade de vida", 97.56, "star"]] },
];
const P_ICONS: [string, string][] = [[BLU, "brief"], [ORANGE, "spark"], [YEL, "family"], [PINK, "incl"], [NAVY, "lib"]];

export const SaberMais: React.FC = () => {
  const f = useCurrentFrame();
  const tau = f / SM_FPS;
  const t = interpolate(tau, WARP_N, WARP_O);
  const tn = NR0 + tau - NR_IN;
  const dot = lin(t, 1.2, 3.7);
