          <Kicker t={t} at={137.59}>Para diferentes tipos de organização</Kicker>
        </div>
        <div style={abs(140, 200)}>
          <Head t={t} size={84} width={1640} items={[["Ele se adapta", 137.67], ["ao seu contexto", 138.33, true]]} />
        </div>
        {[
          ["build", BLU, "Empresas", 139.65],
          ["users", YEL, "Cooperativas", 140.39],
          ["flag", PINK, "Sindicatos", 141.37],
          ["cap", ORANGE, "Instituições de ensino", 142.47],
          ["land", NAVY, "Órgãos públicos", 144.13],
        ].map(([ic, c, l, at], i) => (
          <div key={i} style={abs(140 + i * 334, 370, { width: 306, display: "flex", flexDirection: "column", alignItems: "center", gap: 20, ...zoom(t, at as number) })}>
            <div style={{ transform: `translateY(${(Math.sin(t * 2 + i) * 14).toFixed(1)}px) rotate(${(Math.sin(t * 1.5 + i * 1.3) * 4).toFixed(2)}deg)` }}>
              <Tile c={c as string} s={210} icon={ic as string} />
            </div>
            <div style={{ fontFamily: HEAD, fontWeight: 800, fontSize: 32, lineHeight: 1.15, color: NAVY, textAlign: "center" }}>{l}</div>
          </div>
        ))}
        <div style={abs(140, 780, { width: 1640, ...rise(t, 145.4, 60, 0.6) })}>
          <Card style={{ padding: "30px 44px", display: "flex", alignItems: "center", gap: 30 }}>
            <div style={{ fontFamily: HEAD, fontWeight: 800, fontSize: 44, color: NAVY, whiteSpace: "nowrap" }}>Projeto desenhado conforme</div>
            {[["o porte", 147.39], ["o segmento", 148.23], ["os objetivos", 149.43]].map(([l, at]) => (
              <div key={l as string} style={{ fontFamily: HEAD, fontWeight: 800, fontSize: 40, color: "#FFFFFF", background: ORANGE, borderRadius: 18, padding: "12px 30px", whiteSpace: "nowrap", ...zoom(t, at as number, 0.4) }}>{l}</div>
            ))}
          </Card>
        </div>
      </Sc>

      {/* 11 — mais de 25 anos */}
      <Sc t={t} a={C.s10} b={C.s11}>
        {[0, 0.33, 0.66].map((dl) => {
          const u = t > 153.2 ? ((t - 153.2) * 0.5 + dl) % 1 : -1;
          return u >= 0 ? <div key={dl} style={abs(960 - 260, 500 - 260, { width: 520, height: 520, borderRadius: 260, border: `12px solid ${TINT[ORANGE]}`, boxSizing: "border-box", opacity: 1 - u, transform: `scale(${(0.5 + u * 1.6).toFixed(3)})` })} /> : null;
        })}
        <div style={abs(0, 240, { width: 1920, display: "flex", flexDirection: "column", alignItems: "center" })}>
          <Body size={40} style={rise(t, 151.59, 20)}>
            Por trás disso,
          </Body>
          <div style={{ display: "flex", alignItems: "baseline", gap: 30, marginTop: 6 }}>
            <div style={{ fontFamily: HEAD, fontWeight: 800, fontSize: 110, color: NAVY, ...rise(t, 152.61, 40) }}>mais de</div>
            <div style={{ fontFamily: HEAD, fontWeight: 800, fontSize: 380, lineHeight: 1, color: ORANGE, letterSpacing: "-0.04em", ...zoom(t, 153.2, 0.5) }}>{Math.round(interpolate(t, [153.2, 154.0], [1, 25], { ...cl, easing: OUT }))}</div>
            <div style={{ fontFamily: HEAD, fontWeight: 800, fontSize: 110, color: NAVY, ...rise(t, 153.77, 40) }}>anos</div>
          </div>
          <div style={{ marginTop: 10 }}>
            <Head t={t} size={66} width={1500} align="center" items={[["de experiência", 154.15], ["no setor educacional", 154.77, true]]} />
          </div>
        </div>
      </Sc>

      {/* 12 — da apresentação à implantação */}
      <Sc t={t} a={C.s11} b={C.s12}>
        <div style={abs(140, 150)}>
          <Kicker t={t} at={156.5}>Da apresentação à implantação</Kicker>
        </div>
        <div style={abs(140, 220)}>
          <Head t={t} size={84} width={1640} items={[["O caminho", 156.6], ["é simples", 156.96, true]]} />
        </div>
        <div style={abs(260, 552, { width: 1400, height: 10, borderRadius: 5, background: TINT[NAVY] })} />
        <div style={abs(260, 552, { width: 1400 * interpolate(t, [158.06, 159.34, 161.18, 163.08], [0, 0.333, 0.666, 1], cl), height: 10, borderRadius: 5, background: ORANGE })} />
        {[
          ["chat", BLU, "Apresentação", "comercial", 158.06],
          ["doc", YEL, "Desenho", "da proposta", 159.34],
          ["key", PINK, "Definição", "dos acessos", 161.18],
          ["rocket", ORANGE, "Implantação", "", 163.08],
        ].map(([ic, c, l1, l2, at], i) => (
          <div key={i} style={abs(260 + i * 466.6 - 170, 462, { width: 340, display: "flex", flexDirection: "column", alignItems: "center", gap: 22, ...zoom(t, at as number) })}>
            <Tile c={c as string} s={190} icon={ic as string} />
            <div style={{ fontFamily: HEAD, fontWeight: 700, fontSize: 28, letterSpacing: "0.18em", color: ORANGE }}>0{i + 1}</div>
            <div style={{ fontFamily: HEAD, fontWeight: 800, fontSize: 40, lineHeight: 1.14, color: NAVY, textAlign: "center" }}>
              {l1}
              <br />
              {l2}
            </div>
          </div>
        ))}
      </Sc>

      {/* 13 — chamada: agende uma apresentação */}
      <Sc t={t} a={C.s12} b={C.end} navy>
        <div style={abs(0, 150, { width: 1920, display: "flex", justifyContent: "center" })}>
          <Head t={t} size={96} width={1500} align="center" color="#FFFFFF" hl={YEL} items={[["Dê o", 164.7], ["primeiro passo.", 164.94, true]]} />
        </div>
        {(() => {
          const tap = 167.75;
          const press = t > tap && t < tap + 0.16 ? 1 : 0;
          const hand = interpolate(t, [167.0, tap], [0, 1], { ...cl, easing: OUT });
          return (
            <>
              <div style={abs(0, 380, { width: 1920, display: "flex", justifyContent: "center" })}>
                <div style={{ background: ORANGE, borderRadius: 36, padding: "40px 80px 44px", display: "flex", alignItems: "center", gap: 30, color: "#FFFFFF", boxShadow: "0 30px 70px rgba(0,0,0,0.35)", transform: `scale(${(pop(t, 166.0, 0.5) * (1 - press * 0.05) * (1 + 0.012 * Math.sin(t * 5))).toFixed(4)})` }}>
                  <Icon n="cal" s={96} w={2} />
                  <div style={{ fontFamily: HEAD, fontWeight: 800, fontSize: 84, letterSpacing: "-0.02em", whiteSpace: "nowrap" }}>Agende uma apresentação</div>
                </div>
              </div>
              {[0, 0.5].map((dl) => {
                const u = t > tap ? ((t - tap) * 0.9 + dl) % 1 : -1;
                return u >= 0 && t < tap + 2.2 ? <div key={dl} style={abs(960 - 640, 380 - 6, { width: 1280, height: 200, borderRadius: 44, border: "5px solid rgba(255,255,255,0.6)", boxSizing: "border-box", opacity: 0.7 * (1 - u), transform: `scale(${(1 + u * 0.12).toFixed(3)}, ${(1 + u * 0.4).toFixed(3)})` })} /> : null;
              })}
              <svg width={110} height={126} viewBox="0 0 30 34" style={abs(1380 + (1 - hand) * 300, 500 + (1 - hand) * 340, { opacity: t >= 167.0 && t < 169.3 ? 1 : 0, transform: `scale(${(1 - press * 0.15).toFixed(3)})`, transformOrigin: "10% 5%" })}>
                <path d="M3 2 L3 25 L9 19.500 L13.500 30 L18 28 L13.500 18 L22 18 Z" fill="#FFFFFF" stroke={NAVY} strokeWidth={2} strokeLinejoin="round" />
              </svg>
            </>
          );
        })()}
        <div style={abs(0, 690, { width: 1920, display: "flex", justifyContent: "center" })}>
          <Head t={t} size={56} width={1500} align="center" color="#FFFFFF" hl={YEL} weight={700} items={[["e descubra como o", 169.12], ["Plano de Educação", 170.1, true], ["Rede Saber Mais", 171.18, true], ["pode se adaptar", 172.43], ["à realidade", 173.51], ["da sua organização.", 174.21]]} />
        </div>
      </Sc>
      <Sc t={t} a={C.end} b={999}>
        <div style={abs(0, 80, { width: 1920, display: "flex", justifyContent: "center", ...zoom(t, 175.75, 0.55) })}>
          <Card style={{ padding: "16px 50px", borderRadius: 48 }}>
            <Img src={LOGO} style={{ height: 330, display: "block" }} />
          </Card>
        </div>
        <div style={abs(0, 480, { width: 1920, display: "flex", justifyContent: "center" })}>
          <Head t={t} size={96} width={1700} align="center" items={[["Educação que", 177.19], ["transforma", 178.19, true], ["famílias.", 178.89, true]]} />
        </div>
        <div style={abs(0, 740, { width: 1920, display: "flex", flexDirection: "column", alignItems: "center", gap: 26 })}>
          <div style={{ background: ORANGE, borderRadius: 26, padding: "22px 56px 26px", display: "flex", alignItems: "center", gap: 22, color: "#FFFFFF", transform: `scale(${(pop(t, 179.4, 0.5) * (1 + 0.014 * Math.sin(t * 5))).toFixed(4)})`, opacity: t >= 179.4 ? 1 : 0 }}>
            <Icon n="cal" s={56} w={2.200} />
            <div style={{ fontFamily: HEAD, fontWeight: 800, fontSize: 52, whiteSpace: "nowrap" }}>Agende uma apresentação</div>
          </div>
          <div style={{ fontFamily: HEAD, fontWeight: 700, fontSize: 40, color: NAVY, letterSpacing: "0.02em", ...rise(t, 180.0, 20) }}>lp.redesabermais.com</div>
        </div>
      </Sc>

      {/* 9b — NR-1 e ESG (pedido do cliente em 13/10) */}
      {tau >= NR_IN && tau < NR_OUT ? (
        <Sc t={tn} a={NR0} b={NR0 + NR_OUT - NR_IN}>
          <div style={abs(0, 200, { width: 1920, display: "flex", justifyContent: "center" })}>
            <Head t={tn} size={80} width={1500} align="center" items={[["O Plano de Educação", NR0 + NR_T.plano], ["ainda ajuda", NR0 + NR_T.ajuda], ["a sua empresa", NR0 + NR_T.empresa], ["a atender", NR0 + NR_T.atender, true]]} />
          </div>
          {[
            ["doc", BLU, "NR-1", NR_T.nr],
            ["star", YEL, "ESG", NR_T.esg],
          ].map(([ic, c, l, at], i) => (
            <div key={i} style={abs(220 + i * 780, 500, rise(tn, NR0 + (at as number), 120, 0.55))}>
              <Float t={tn} i={i} amp={10}>
                <Card style={{ width: 700, height: 360, padding: "0 60px", display: "flex", alignItems: "center", gap: 50 }}>
                  <div style={{ position: "relative", transform: `scale(${pop(tn, NR0 + (at as number) + 0.1).toFixed(3)}) rotate(${(Math.sin(tn * 2 + i) * 4).toFixed(2)}deg)` }}>
                    <Tile c={c as string} s={200} icon={ic as string} />
                    <div style={{ position: "absolute", right: -22, bottom: -22, ...zoom(tn, NR0 + (at as number) + 0.35, 0.4) }}>
                      <Tile c={ORANGE} s={84} icon="check" style={{ boxShadow: "0 0 0 8px #FFFFFF" }} />
                    </div>
                  </div>
                  <div style={{ fontFamily: HEAD, fontWeight: 800, fontSize: 150, letterSpacing: "-0.03em", color: NAVY, whiteSpace: "nowrap" }}>{l}</div>
                </Card>
              </Float>
            </div>
          ))}
        </Sc>
      ) : null}
      <Cut t={tau} at={NR_IN} i={2} />

      {CUTS.map((c, i) => (
        <Cut key={i} t={t} at={c} i={i} />
      ))}
      {/* abertura: os blocos da marca saem da tela */}
      {t < 0.3 ? <div style={{ position: "absolute", left: -200, top: -100, width: 2320, height: 1280, borderRadius: 160, background: ORANGE, transform: `translateX(${(lin(t, 0, 0.3) * 2500).toFixed(0)}px)` }} /> : null}
    </AbsoluteFill>
  );
};

